package com.fakelegacy.customer;

import java.sql.ResultSet;
import java.sql.SQLException;

import org.springframework.jdbc.core.RowMapper;

public class CustomerRowMapper implements RowMapper<Customer> {

    @Override
    public Customer mapRow(ResultSet rs, int rowNum) throws SQLException {
        Customer c = new Customer();
        c.setId(rs.getLong("id"));
        c.setEmail(rs.getString("email"));
        c.setType(rs.getString("customer_type"));
        c.setCompanyName(rs.getString("company_name"));
        c.setVatNumber(rs.getString("vat_number"));
        c.setRegisteredAt(rs.getTimestamp("registered_at").toLocalDateTime());
        c.setBlacklisted(rs.getBoolean("blacklisted"));
        c.setTierOverride(rs.getString("tier_override"));
        c.setLoyaltyPoints(rs.getInt("loyalty_points"));
        c.setCreditLimit(rs.getBigDecimal("credit_limit"));
        c.setCreditOutstanding(rs.getBigDecimal("credit_outstanding"));
        c.setLegacyRef(rs.getString("legacy_ref"));
        // business customers are never below SILVER
        if ("B2B".equals(c.getType())) {
            c.setMinTier("SILVER");
        }
        return c;
    }
}
